// Generated by packages/academy/scripts/build-content.ts. Don't edit by hand.
export default JSON.parse("{\"3.14.1\":{\"unit\":\"3.14\",\"courseId\":\"3.14.1\",\"bridge\":\"In 3.13.8 you graded strategies, several of which trade futures. 3.13.1 sketched LXF in one paragraph; here's the full contract. 2.14.6's margin is now settled in cash every day, 1.4.7's leverage comes built in, and 1.4.4's stop sizing meets whole contracts.\",\"hook\":{\"prompt\":\"LXF, the synthetic index future, is worth 50 vUSD per point and trades at 5,000.00. You buy 2 contracts. By the close, price is 4,962.50. How much leaves your account tonight?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":10000,\"step\":50,\"unit\":\" vUSD\",\"start\":1000,\"answer\":3750,\"tolerance\":0,\"feedback\":[{\"from\":0,\"to\":1900,\"text\":\"That's one contract or less. One LXF loses 37.50 × 50 = 1,875.00, and you hold two.\"},{\"from\":1950,\"to\":3700,\"text\":\"Count the points first: 5,000.00 − 4,962.50 = 37.50. Then × 50 vUSD × 2 contracts.\"},{\"from\":3800,\"to\":10000,\"text\":\"Too much. 37.50 points × 50 vUSD × 2 contracts covers the whole move.\"}]},\"compare\":\"You picked {yours}. 37.50 points × 50 vUSD × 2 contracts = 3,750.00, paid in cash tonight as variation margin, whatever your plan says.\",\"concept\":\"futures-contract\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"What a future is\",\"text\":\"A [[futures|futures contract]] is a standard agreement, traded on an exchange, to buy or sell an underlying on a set date. A clearing house stands between buyer and seller. The [[contract-multiplier]] turns points into money; the [[tick-value]] is the money in one minimum step, a [[tick]].\"},{\"kind\":\"match\",\"title\":\"Synthetic contract specs\",\"prompt\":\"Tick value = tick size × value per point. Match each synthetic contract to what its step is worth.\",\"columns\":[\"Contract\",\"Value\"],\"pairs\":[{\"left\":\"LXF: 50 vUSD a point, tick 0.25\",\"right\":\"12.50 vUSD a tick\",\"wrong\":\"A quarter of a point × 50 vUSD = 12.50.\"},{\"left\":\"LXM, the micro: 5 vUSD a point, tick 0.25\",\"right\":\"1.25 vUSD a tick\",\"wrong\":\"LXM is a tenth of LXF: 0.25 × 5 = 1.25.\"},{\"left\":\"LXO, crude: 1,000 units, tick 0.01\",\"right\":\"10.00 vUSD a tick\",\"wrong\":\"A 0.01 move on 1,000 units is 10.00.\"},{\"left\":\"LXO, crude: a 1.00 move\",\"right\":\"1,000.00 vUSD a contract\",\"wrong\":\"1.00 on 1,000 units is 1,000.00: a hundred ticks of 10.00.\"}],\"correct\":\"Right. These synthetic contracts copy the shape of real ones: an index future, its micro and crude oil. Real specs are on each exchange's contract page.\",\"concept\":\"futures-contract\"},{\"kind\":\"worked\",\"title\":\"Built-in leverage\",\"lines\":[\"One LXF at 5,000.00 controls 5,000.00 × 50 = 250,000.00 of the index: its [[notional-value|notional value]].\",\"In this example the exchange asks 12,500.00 of [[initial-margin|initial margin]] per contract: 5% of that value.\",\"Implied leverage = 250,000.00 ÷ 12,500.00 = ?\"],\"ask\":{\"answer\":20,\"tolerance\":0,\"unit\":\"×\",\"feedback\":[{\"value\":5,\"text\":\"5 is the margin as a percentage. Leverage is the contract's value divided by the margin.\"},{\"value\":0.05,\"text\":\"That's margin ÷ value. Flip it: value ÷ margin.\"}],\"correct\":\"Right: 20×. A 1% index move, 50 points, is 2,500.00: a fifth of the margin.\"},\"after\":\"Exchange margins are usually a small share of the contract's value, so the leverage is built in. The margin is a deposit, not a measure of risk: the stop and the size are.\",\"concept\":\"leverage\"},{\"kind\":\"figure\",\"title\":\"Settled in cash, every day\",\"text\":\"Every evening the exchange marks each position to the settlement price and moves the gain or loss in cash: the [[variation-margin|variation margin]]. Fall below the [[maintenance-margin|maintenance margin]] and you must top up to the initial level, or the broker closes the position.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":25000,\"h\":25000,\"l\":25000,\"c\":25000},{\"o\":21250,\"h\":21250,\"l\":21250,\"c\":21250},{\"o\":17250,\"h\":17250,\"l\":17250,\"c\":17250},{\"o\":25000,\"h\":25000,\"l\":25000,\"c\":25000},{\"o\":25000,\"h\":25000,\"l\":25000,\"c\":25000}],\"style\":\"line\",\"range\":[15000,28000],\"describe\":\"A margin balance over five points in time: 25,000 posted, 21,250 after day 1, 17,250 after day 2, back to 25,000 after a top-up, then unchanged while the maintenance level is raised to 26,000.\"},\"steps\":[{\"text\":\"You post 25,000.00 of initial margin for 2 LXF: 12,500.00 each.\",\"visible\":1,\"layers\":[{\"kind\":\"level\",\"price\":25000,\"role\":\"neutral\",\"label\":\"INITIAL 25,000\"},{\"kind\":\"level\",\"price\":20000,\"role\":\"stop\",\"label\":\"MAINTENANCE 20,000\"}]},{\"text\":\"Day 1: LXF settles 37.50 lower. 3,750.00 leaves in cash; 21,250.00 remain.\",\"visible\":2},{\"text\":\"Day 2: 40 more points, −4,000.00. 17,250.00 is below 20,000.00: margin call. You add 7,750.00.\",\"visible\":4},{\"text\":\"The exchange raises maintenance to 13,000.00 a contract. Price is flat, yet 25,000.00 now triggers a call.\",\"visible\":5,\"layers\":[{\"kind\":\"level\",\"price\":26000,\"role\":\"concept\",\"label\":\"NEW MAINTENANCE 26,000\"}]}]},\"concept\":\"mark-to-market\"},{\"kind\":\"worked\",\"title\":\"Whole contracts from the stop\",\"lines\":[\"Futures lessons use a 100,000.00 account, so one contract can fit. Risk 1% = 1,000.00.\",\"Stop 20 points: 20 × 50 = 1,000.00 per LXF. One contract fits exactly.\",\"Stop 45 points: 2,250.00 per LXF. Even one breaks the rule: 0 LXF.\",\"A [[micro-contract|micro]], LXM, is a tenth of the size: 45 × 5 = 225.00 per contract.\",\"LXM contracts within 1,000.00: ?\"],\"ask\":{\"answer\":4,\"tolerance\":0,\"unit\":\"LXM\",\"feedback\":[{\"value\":5,\"text\":\"5 × 225.00 = 1,125.00: over the 1,000.00 budget. Round down.\"},{\"value\":0,\"text\":\"That's the full-size answer. An LXM risks a tenth as much: 225.00.\"},{\"value\":44,\"text\":\"Each LXM risks 45 points × 5 = 225.00, not 22.50.\"}],\"correct\":\"Right: 4 LXM risk 900.00 at the stop, before fees.\",\"incorrect\":\"1,000.00 ÷ 225.00, rounded down to whole contracts.\"},\"after\":\"Whole contracts make sizing lumpy: with LXF alone the choice was 0 or 2,250.00 of risk. Micros cut the step to 225.00. The margin never entered the sum.\",\"concept\":\"futures-contract\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Low intraday margins from brokers invite oversizing. Exchanges can halt trading at price limits, and prices gap across session breaks. Client money sits in [[segregated-funds|segregated accounts]], but protection varies: in the US, SIPC doesn't cover futures, and a broker's failure can freeze funds for months.\"},{\"kind\":\"fields\",\"title\":\"Your turn: LXF or LXM?\",\"prompt\":\"Account 100,000.00, risk 1%. LXF at 5,000.00, stop 30 points. Choose LXF and LXM contracts so the loss at the stop is as large as fits within 1,000.00.\",\"fields\":[{\"id\":\"lxf\",\"label\":\"LXF contracts (50 vUSD a point)\",\"kind\":\"stepper\",\"min\":0,\"max\":3,\"step\":1,\"default\":1},{\"id\":\"lxm\",\"label\":\"LXM contracts (5 vUSD a point)\",\"kind\":\"stepper\",\"min\":0,\"max\":12,\"step\":1,\"default\":0}],\"valid\":{\"all\":[{\"field\":\"lxf\",\"eq\":0},{\"field\":\"lxm\",\"eq\":6}]},\"feedback\":[{\"when\":{\"field\":\"lxf\",\"gte\":1},\"text\":\"One LXF risks 30 × 50 = 1,500.00 at the stop: over the 1,000.00 budget on its own. Use micros.\"},{\"when\":{\"field\":\"lxm\",\"gt\":6},\"text\":\"Each LXM risks 30 × 5 = 150.00 at the stop, so {lxm} of them go over 1,000.00.\"},{\"when\":{\"field\":\"lxm\",\"lt\":6},\"text\":\"That fits, but leaves room: each LXM risks 150.00, and 1,000.00 holds more of them.\"}],\"correct\":\"Right: 0 LXF and 6 LXM, 900.00 at the stop. A seventh would make it 1,050.00.\",\"concept\":\"futures-contract\"}],\"check\":[\"q-3.14.1-1\",\"q-3.14.1-2\",\"q-3.14.1-3\"],\"recap\":{\"takeaways\":[\"The multiplier turns points into money: 37.50 points × 50 × 2 LXF = 3,750.00 tonight.\",\"Gains and losses settle in cash daily; below maintenance margin, you top up to initial.\",\"Size from the stop in whole contracts; when one is too big, use micros: 6 LXM.\"],\"next\":\"Next, 3.14.2: futures expire, so you roll to the next contract, and continuous charts need adjusting.\"}},\"3.14.2\":{\"unit\":\"3.14\",\"courseId\":\"3.14.2\",\"bridge\":\"In 3.14.1 a contract settled every day. It also ends: here you roll it to the next expiry with one order. 3.11.3 asked for adjusted prices before any test; continuous futures charts need that too, or backtests trade gaps nobody had.\",\"hook\":{\"prompt\":\"On roll day, the LXF continuous chart jumps 30 points overnight, with no news. Did holders of the expiring contract just earn 30 points?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"yes\",\"label\":\"Yes\",\"feedback\":\"March holders saw no jump: March closed at 5,000.00. The chart switched to June, which trades 30 points higher.\"},{\"id\":\"no\",\"label\":\"No\"}],\"answer\":\"no\"},\"compare\":\"You picked {yours}. No: the chart switched from the expiring contract to the next one, 30 points higher. Nobody earned the gap; it exists only on the chart.\",\"concept\":\"continuous-contract\"},\"learn\":[{\"kind\":\"match\",\"title\":\"Month codes\",\"prompt\":\"A contract's name is root + month code + year: LXFZ6 is the December 2026 LXF. Match the quarterly codes that index futures use.\",\"columns\":[\"Code\",\"Month\"],\"pairs\":[{\"left\":\"H\",\"right\":\"March\",\"wrong\":\"H is March, the first quarterly month.\"},{\"left\":\"M\",\"right\":\"June\",\"wrong\":\"M is June.\"},{\"left\":\"U\",\"right\":\"September\",\"wrong\":\"U is September.\"},{\"left\":\"Z\",\"right\":\"December\",\"wrong\":\"Z is December, the last month of the year and of the alphabet.\"}],\"correct\":\"Right. Every month has a code: F, G, H, J, K, M, N, Q, U, V, X and Z, January to December. Crude oil lists every month.\",\"concept\":\"contract-roll\"},{\"kind\":\"explain\",\"title\":\"How a contract ends\",\"text\":\"At [[expiry]] a contract ends. Index futures settle in cash. Others end in [[physical-delivery]], the actual goods changing hands: from the [[first-notice-day]], a long can be told to take the commodity, so the simulator forces you out before it. Trading moves to the next contract days before expiry; rolling when it moves keeps costs low.\"},{\"kind\":\"figure\",\"title\":\"The roll is one order\",\"text\":\"A [[calendar-spread]] buys one expiry and sells another as a single order. You cross one bid/ask instead of two, and price can't move between the legs. That's how a roll is done.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":4978.75,\"h\":4978.75,\"l\":4978.75,\"c\":4978.75},{\"o\":4986.5,\"h\":4986.5,\"l\":4986.5,\"c\":4986.5},{\"o\":4983.25,\"h\":4983.25,\"l\":4983.25,\"c\":4983.25},{\"o\":4975,\"h\":4975,\"l\":4975,\"c\":4975},{\"o\":4984.75,\"h\":4984.75,\"l\":4984.75,\"c\":4984.75},{\"o\":5000,\"h\":5000,\"l\":5000,\"c\":5000}],\"hideCandles\":true,\"range\":[4960,5045],\"describe\":\"Two lines over six days: the March LXF contract from 4,978.75 to 5,000.00 and the June contract about 30 points above it, ending at 5,030.00.\"},\"steps\":[{\"text\":\"March and June contracts on the same index. June trades about 30 points higher.\",\"layers\":[{\"kind\":\"line\",\"values\":[4978.75,4986.5,4983.25,4975,4984.75,5000],\"role\":\"neutral\",\"label\":\"MARCH\"},{\"kind\":\"line\",\"values\":[5009.25,5016.75,5013.5,5005,5014.75,5030],\"role\":\"accent\",\"label\":\"JUNE\"}]},{\"text\":\"Roll day: one order sells March at 5,000.00 and buys June at 5,030.00.\",\"layers\":[{\"kind\":\"marker\",\"index\":5,\"price\":5000,\"label\":\"SELL MARCH\",\"role\":\"down\"},{\"kind\":\"marker\",\"index\":5,\"price\":5030,\"label\":\"BUY JUNE\",\"role\":\"up\"}]},{\"text\":\"The 30-point gap is carry: three months of financing, 4.0%, minus dividends, 1.6%, on 5,000.\"}]},\"concept\":\"contract-roll\"},{\"kind\":\"worked\",\"title\":\"Your stop moves with the roll\",\"lines\":[\"You're long 2 LXF March at 5,000.00, stop 4,960.00: 40 points of risk.\",\"You roll by spread: sell March at 5,000.00, buy June at 5,030.00. The spread is 30.00.\",\"June trades 30.00 above March. To keep the same 40 points of risk, the June stop goes at: ?\"],\"ask\":{\"answer\":4990,\"tolerance\":0,\"feedback\":[{\"value\":4960,\"text\":\"On June, 4,960.00 is 70 points below 5,030.00: more risk than planned. Add the spread.\"},{\"value\":4930,\"text\":\"That moves it the wrong way. June trades higher, so the stop moves up by 30.00.\"}],\"correct\":\"Right: 4,990.00, still 40 points below the June price.\"},\"after\":\"Move targets and alerts too. The roll costs one order's bid/ask and fees. The 30 points aren't lost at the roll: they're the June contract's carry, which 3.14.3 unpacks.\",\"concept\":\"contract-roll\"},{\"kind\":\"figure\",\"title\":\"Fake gaps on continuous charts\",\"text\":\"A [[continuous-contract|continuous contract]] joins expiring contracts into one long chart. Unadjusted, every roll leaves a gap no holder ever had. [[back-adjustment|Back-adjustment]] shifts all prices before the roll by the gap, so the series runs on without a jump. Proportional adjustment multiplies them by the price ratio instead.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":4972,\"h\":4981.25,\"l\":4966.5,\"c\":4978.75},{\"o\":4978.75,\"h\":4990,\"l\":4974.25,\"c\":4986.5},{\"o\":4986.5,\"h\":4998.75,\"l\":4980,\"c\":4983.25},{\"o\":4983.25,\"h\":4993.5,\"l\":4971.75,\"c\":4975},{\"o\":4975,\"h\":4988.25,\"l\":4969.5,\"c\":4984.75},{\"o\":4984.75,\"h\":4999.25,\"l\":4979,\"c\":4994.5},{\"o\":4994.5,\"h\":5000.75,\"l\":4985.25,\"c\":4989},{\"o\":4989,\"h\":5002.5,\"l\":4983.75,\"c\":5000},{\"o\":5029.5,\"h\":5031.75,\"l\":5022.25,\"c\":5025.5},{\"o\":5025.5,\"h\":5030.25,\"l\":5016.75,\"c\":5019},{\"o\":5019,\"h\":5027.5,\"l\":5011.25,\"c\":5024.25},{\"o\":5024.25,\"h\":5029.75,\"l\":5017.5,\"c\":5021}],\"range\":[4960,5045],\"describe\":\"Twelve daily candles of a continuous LXF chart. Eight March candles stay below 5,002.50 and close at 5,000.00 on roll day; the chart then switches to June, which opens at 5,029.50, looking like a breakout.\"},\"steps\":[{\"text\":\"Unadjusted: March prices until the roll, then June. Price seems to break out overnight.\",\"layers\":[{\"kind\":\"level\",\"price\":5002.5,\"role\":\"resistance\",\"label\":\"MARCH HIGH 5,002.50\"}]},{\"text\":\"Back-adjusted: add the 30.00 roll gap to every March price. The breakout disappears.\",\"layers\":[{\"kind\":\"line\",\"values\":[5008.75,5016.5,5013.25,5005,5014.75,5024.5,5019,5030,5025.5,5019,5024.25,5021],\"role\":\"accent\",\"label\":\"BACK-ADJUSTED\"},{\"kind\":\"level\",\"price\":5032.5,\"role\":\"concept\",\"label\":\"ADJUSTED HIGH 5,032.50\"}]}]},\"concept\":\"continuous-contract\"},{\"kind\":\"worked\",\"title\":\"Back-adjust a price\",\"lines\":[\"Roll day: March closes at 5,000.00, June at 5,030.00. The gap is 30.00.\",\"Back-adjustment adds 30.00 to every price before the roll; prices after it stay as traded.\",\"A bar from before the roll closed at 4,962.50. Its adjusted close: ?\"],\"ask\":{\"answer\":4992.5,\"tolerance\":0.01,\"feedback\":[{\"value\":4932.5,\"text\":\"Subtracting widens the gap. Earlier prices move up to meet June's level.\"},{\"value\":4962.5,\"text\":\"That's the unadjusted close. Every price before the roll shifts by the gap.\"}],\"correct\":\"Right: 4,992.50. Proportional adjustment gives 4,962.50 × 5,030 ÷ 5,000 = 4,992.28.\"},\"after\":\"Signals and backtests use the adjusted series; fills, stops and P&L use the real contract's prices. Over many rolls, additive adjustment can even push old prices below zero, so percentage maths needs the proportional kind.\",\"concept\":\"continuous-contract\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Delivery is real. In April 2020, the expiring US crude oil future settled below zero, near −37 dollars a barrel, as storage filled up: holders who couldn't take delivery paid to get out. On physically delivered contracts, roll before first notice day.\"},{\"kind\":\"order\",\"title\":\"Your turn: roll the LXO long\",\"prompt\":\"You're long LXO crude, 6 days before first notice day, and volume is moving to the next month. Put the roll in order.\",\"items\":[\"Check the first notice day and which month the volume is in\",\"Send one calendar-spread order: sell the front month, buy the next\",\"Move the stop and target by the spread\",\"Back-adjust the chart: add the roll gap to every earlier price\",\"Check the adjusted series: no gap left at the roll\"],\"explain\":\"Date first, then one spread order, then the risk, then the data. In this order the position never sits past first notice day, the stop keeps its distance, and no backtest sees a fake gap.\",\"wrong\":\"A roll is a trade first: date it, execute it as one order, fix the stop, then fix the chart.\",\"concept\":\"contract-roll\"}],\"check\":[\"q-3.14.2-1\",\"q-3.14.2-2\",\"q-3.14.2-3\"],\"recap\":{\"takeaways\":[\"Month codes name expiries (H, M, U, Z); roll before expiry, and before first notice day.\",\"Roll with one calendar-spread order, then shift the stop by the spread: 4,960 becomes 4,990.\",\"Back-adjust continuous charts: add each roll gap to earlier prices, or backtests trade fake gaps.\"],\"next\":\"Next, 3.14.3: why June traded 30 points above March. Contango, backwardation and the roll yield a rolled position earns or pays.\"}},\"3.14.3\":{\"unit\":\"3.14\",\"courseId\":\"3.14.3\",\"bridge\":\"In 3.14.2 June traded 30 points above March, and your stop moved up by that gap. Here is the whole curve: contango, backwardation, and the roll yield a rolled long pays or earns. 3.13.3 called roll yield a kind of carry; now you compute it.\",\"hook\":{\"prompt\":\"Spot crude stays at 70.00 all year. The one-month future always trades at 71.00, and you roll every month. After 12 months, your long position has…\",\"control\":{\"kind\":\"slider\",\"min\":-30,\"max\":30,\"step\":0.5,\"unit\":\"%\",\"start\":0,\"answer\":-15.5,\"tolerance\":1.5,\"feedback\":[{\"from\":-30,\"to\":-17.5,\"text\":\"That's more than twelve rolls lose. Each month the future falls from 71.00 to 70.00: −1.41%.\"},{\"from\":-13.5,\"to\":-0.5,\"text\":\"Each roll buys at 71.00 and ends at 70.00: −1.41% a month, twelve times over.\"},{\"from\":0,\"to\":30,\"text\":\"Spot is flat, but the future isn't: it falls from 71.00 to 70.00 every month as it converges.\"}]},\"compare\":\"You picked {yours}. Each roll buys at 71.00 and the contract converges to 70.00: −1.41% a month, (1 − 0.0141)¹² − 1 = −15.7% a year, with spot flat.\",\"concept\":\"roll-yield\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"Two shapes of curve\",\"text\":\"The term structure plots futures prices by expiry. Left to right: spot, then contracts one to six months out. Each contract converges to spot as it ages.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":70,\"h\":70,\"l\":70,\"c\":70},{\"o\":70,\"h\":70,\"l\":70,\"c\":70},{\"o\":70,\"h\":70,\"l\":70,\"c\":70},{\"o\":70,\"h\":70,\"l\":70,\"c\":70},{\"o\":70,\"h\":70,\"l\":70,\"c\":70},{\"o\":70,\"h\":70,\"l\":70,\"c\":70},{\"o\":70,\"h\":70,\"l\":70,\"c\":70}],\"hideCandles\":true,\"range\":[64,76],\"describe\":\"Futures prices by expiry, from spot at 70.00 to six months out. The contango curve rises to 74.50; the backwardation curve falls to 66.00.\"},\"steps\":[{\"text\":\"Contango: futures above spot. Storage, financing and insurance cost money until delivery.\",\"layers\":[{\"kind\":\"level\",\"price\":70,\"role\":\"neutral\",\"label\":\"SPOT 70.00\"},{\"kind\":\"line\",\"values\":[70,71,71.9,72.7,73.4,74,74.5],\"role\":\"down\",\"label\":\"CONTANGO\"}]},{\"text\":\"Backwardation: futures below spot. When stocks are short, a barrel today is worth more.\",\"layers\":[{\"kind\":\"line\",\"values\":[70,69,68.2,67.5,66.9,66.4,66],\"role\":\"up\",\"label\":\"BACKWARDATION\"}]},{\"text\":\"A month later, if nothing changes, the 71.00 contract has become spot: 70.00.\",\"layers\":[{\"kind\":\"path\",\"points\":[{\"index\":1,\"price\":71},{\"index\":0,\"price\":70}],\"role\":\"accent\",\"label\":\"ONE MONTH ON\",\"dashed\":true}]}]},\"concept\":\"term-structure\"},{\"kind\":\"worked\",\"title\":\"Roll yield\",\"lines\":[\"Contango: you buy the one-month future at 71.00; by expiry it converges to spot, 70.00.\",\"Per roll: 70.00 ÷ 71.00 − 1 = −1.41%. Twelve rolls: (1 − 0.0141)¹² − 1 = −15.7% a year.\",\"Backwardation: spot 70.00, one-month future 69.00. Roll yield per month, in %: ?\"],\"ask\":{\"answer\":1.45,\"tolerance\":0.01,\"unit\":\"%\",\"feedback\":[{\"value\":-1.43,\"text\":\"That's 69 ÷ 70 − 1, the wrong way round. The future rises from 69.00 to 70.00.\"},{\"value\":1.43,\"text\":\"That divides by spot. You paid 69.00, so divide the 1.00 gain by 69.00.\"}],\"correct\":\"Right: +1.45% a month, about +18.8% a year if the curve stayed the same.\"},\"after\":\"That's [[roll-yield]]: what a rolled position earns or pays as each contract converges to spot. In [[contango]] a long pays it; in [[backwardation]] a long earns it. Curves and spot rarely stay put, so it's a tilt, not a promise.\",\"concept\":\"roll-yield\"},{\"kind\":\"worked\",\"title\":\"Why the curve has a shape\",\"lines\":[\"Fair future ≈ spot + financing + storage − [[convenience-yield]]. Financing and storage are the [[cost-of-carry]].\",\"Spot 70.00. Financing at 6% a year: 70.00 × 6% ÷ 12 = 0.35 a month.\",\"Storage and insurance: 0.65 a month. No convenience yield.\",\"Fair one-month future: ?\"],\"ask\":{\"answer\":71,\"tolerance\":0.01,\"feedback\":[{\"value\":70.35,\"text\":\"That covers financing only. Storage and insurance add 0.65.\"},{\"value\":70.65,\"text\":\"Add the financing too: 0.35.\"}],\"correct\":\"Right: 71.00, the hook's contango. The carry sets the curve's slope.\"},\"after\":\"When stocks run low, the barrel in hand has a value of its own, the convenience yield. It can outweigh the carry and tip the curve into backwardation.\",\"concept\":\"term-structure\"},{\"kind\":\"predict\",\"title\":\"A commodity ETF\",\"prompt\":\"A commodity ETF holds the front-month future and rolls monthly. For a year, spot stays at 70.00 and the curve looks like the hook's. Before fees, the ETF…\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"flat\",\"label\":\"Ends flat, like spot\",\"feedback\":\"It doesn't hold spot. It holds futures bought at 71.00 that keep converging down to 70.00.\"},{\"id\":\"down\",\"label\":\"Falls about 16%\"},{\"id\":\"up\",\"label\":\"Rises: it earns the premium\",\"feedback\":\"In contango the long pays the premium: each contract loses it as it converges.\"}],\"answer\":\"down\"},\"reveal\":\"It falls about 15.7%, the roll yield, before fees. Products on VIX futures work the same way: that curve is usually in contango, so long VIX products tend to lose value when nothing happens. Check what a fund holds, not just its name.\",\"concept\":\"roll-yield\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Roll yield is a kind of carry: what a position earns or pays if prices don't move, like the interest gap in FX [[carry]]. Positive carry often comes with crash risk; 3.13.3 tests carry strategies.\"},{\"kind\":\"fields\",\"title\":\"Your turn: build the curve\",\"prompt\":\"Spot stays at 70.00. Set the one-month future so a long that rolls every month earns at least 1% a month.\",\"fields\":[{\"id\":\"future\",\"label\":\"One-month future\",\"kind\":\"stepper\",\"min\":66,\"max\":74,\"step\":0.1,\"default\":71}],\"valid\":{\"field\":\"future\",\"lte\":69.3},\"feedback\":[{\"when\":{\"field\":\"future\",\"gte\":70},\"text\":\"That's not below spot. A long gains nothing, or pays, as the future converges to 70.00.\"},{\"when\":{\"field\":\"future\",\"gt\":69.3},\"text\":\"Backwardation, but not enough: spot ÷ future − 1 is still under 1% a month. Go lower.\"}],\"correct\":\"Right: at 69.30 or lower, 70.00 ÷ 69.30 − 1 = 1.01% a month, as long as spot and the curve stay put.\",\"concept\":\"roll-yield\"}],\"check\":[\"q-3.14.3-1\",\"q-3.14.3-2\",\"q-3.14.3-3\"],\"recap\":{\"takeaways\":[\"Contango: futures above spot (storage, financing). Backwardation: below spot, when stocks are short.\",\"Roll yield ≈ spot ÷ future − 1 per roll: 71.00 against 70.00 costs 1.41% a month.\",\"Rolled longs in contango, like many commodity ETFs and long VIX products, lose while spot is flat.\"],\"next\":\"Next, 3.14.4: commodities, where supply shocks, scheduled reports and limit moves decide what a stop can do.\"}},\"3.14.4\":{\"unit\":\"3.14\",\"courseId\":\"3.14.4\",\"bridge\":\"In 3.14.3 the curve priced storage and scarcity. Now what moves commodity prices: supply shocks, 3.6.5's drivers, and scheduled reports judged by 2.10.1's surprise. Limit moves can lock a market past your stop, so you size 3.14.1's contracts for the gap.\",\"hook\":{\"prompt\":\"A synthetic grain future is locked limit-down for two days. Your stop sits 3% below entry; the daily limit is 5%. Where can your stop fill?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"At −3%\",\"feedback\":\"A stop needs someone to trade with. Locked limit-down means no buyers at any allowed price, so nothing fills.\"},{\"id\":\"b\",\"label\":\"At −5%\",\"feedback\":\"Trading stops at the limit, but nobody buys there: the market is locked. The next day can lock lower again.\"},{\"id\":\"c\",\"label\":\"Only when trading resumes, possibly near −10% or worse\"}],\"answer\":\"c\"},\"compare\":\"You picked {yours}. Locked limit days skip stops: two 5% limits take price 9.75% lower, and the first fill can be lower still.\",\"concept\":\"gap-risk\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"What moves commodities\",\"text\":\"[[commodity|Commodity]] futures come in families: energy, metals, grains and oilseeds, softs such as coffee and sugar, and livestock. Supply shocks move them hardest: weather, OPEC+ output decisions, wars, disease, strikes and export bans. They arrive as jumps, and volatility stays high for a while after.\"},{\"kind\":\"predict\",\"title\":\"An inventory report\",\"prompt\":\"Before a weekly [[inventory-report]], the consensus is that crude stocks fell 2.0 million barrels. The report shows a rise of 1.0 million. What does LXO most likely do first?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"up\",\"label\":\"Rises\",\"feedback\":\"Stocks rose when a fall was expected: more supply than priced in. That pushes price down.\"},{\"id\":\"down\",\"label\":\"Falls\"},{\"id\":\"flat\",\"label\":\"Nothing: a 1.0 million rise is small\",\"feedback\":\"Markets react to the surprise, not the number: up 1.0 million against an expected 2.0 million fall is a 3.0 million miss.\"}],\"answer\":\"down\"},\"reveal\":\"It falls: a 3.0-million-barrel surprise toward more supply. Weekly US oil and gas stock reports, monthly crop estimates such as the USDA's WASDE, and the weekly COT positioning report (3.9.2) are the scheduled ones. Spreads widen and the first minutes swing both ways.\",\"concept\":\"commodity-drivers\"},{\"kind\":\"worked\",\"title\":\"When the stop can't fill\",\"lines\":[\"Long a grain future at 500.00, stop 485.00: 1R = 15.00 a unit. The daily limit is 5%.\",\"Day 1: locked [[limit-move|limit-down]] at 475.00. Nobody buys, so the stop can't fill.\",\"Day 2: locked again, 5% lower: 451.25.\",\"Day 3 reopens at 451.25 and your stop fills there. Loss in R: ?\"],\"ask\":{\"answer\":3.25,\"tolerance\":0.01,\"unit\":\"R\",\"feedback\":[{\"value\":1,\"text\":\"That's the plan. A stop needs a buyer, and a locked market has none.\"},{\"value\":1.67,\"text\":\"That's after one limit day. The market locked again, down to 451.25.\"}],\"correct\":\"Right: 48.75 ÷ 15.00 = 3.25R.\"},\"after\":\"Size from the worst plausible gap, not from the stop. To hold two limit days to 2R here, trade about 0.62 of the stop-based size: 30.00 ÷ 48.75.\",\"concept\":\"gap-risk\"},{\"kind\":\"match\",\"title\":\"Drivers and markets\",\"prompt\":\"Match each driver to the market it moves first.\",\"columns\":[\"Driver\",\"Market\"],\"pairs\":[{\"left\":\"OPEC+ agrees to cut output\",\"right\":\"Crude oil\",\"wrong\":\"OPEC+ sets oil production quotas: a cut tightens crude supply.\"},{\"left\":\"A drought in the growing season\",\"right\":\"Grains such as corn and wheat\",\"wrong\":\"Weather hits crops: a drought shrinks the harvest.\"},{\"left\":\"Real yields fall\",\"right\":\"Gold\",\"wrong\":\"Gold pays no interest, so it tends to gain when real yields fall (3.6.5).\"},{\"left\":\"A colder-than-normal winter forecast\",\"right\":\"Natural gas\",\"wrong\":\"Heating demand drives winter gas: a cold forecast lifts it.\"}],\"correct\":\"Right. Each market has its own drivers; trading one means learning its calendar and its shocks.\",\"concept\":\"commodity-drivers\"},{\"kind\":\"explain\",\"title\":\"Delivery and limits\",\"text\":\"Many commodity futures end in [[physical-delivery]], so roll before first notice day (3.14.2). Many contracts, grains especially, have daily price limits; others pause trading briefly instead. Micro contracts cut the size for smaller accounts. Know which rules your contract has before you hold it through a report.\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Seasonal patterns are public, so the curve prices them: winter natural gas futures already trade above summer ones. Buying winter in summer pays only if winter beats what the curve expected. As a trade, seasonality rates C (3.13.4). Commodities are also the classic ground of trend following (3.13.1).\"},{\"kind\":\"fields\",\"title\":\"Your turn: the report in 10 minutes\",\"prompt\":\"Long 2 LXO at 70.00, stop 69.50: 1R = 1,000.00, 1% of 100,000.00. A report is due in 10 minutes; this drill's daily limit is 1.00. Keep two limit days within 2R.\",\"fields\":[{\"id\":\"contracts\",\"label\":\"LXO contracts held through the report\",\"kind\":\"stepper\",\"min\":0,\"max\":2,\"step\":1,\"default\":2},{\"id\":\"rule\",\"label\":\"Your rule for report days\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Size for two limit days, not for the stop\",\"required\":false}],\"valid\":{\"field\":\"contracts\",\"lte\":1},\"feedback\":[{\"when\":{\"field\":\"contracts\",\"gte\":2},\"text\":\"Two limit days cost 2.00 × 1,000 = 2,000.00 per contract. Two contracts lose 4,000.00: 4R.\"}],\"correct\":\"Right. One contract loses 2,000.00 over two limit days: 2R. Flat also meets the rule: reducing keeps the trade, flat removes the event.\",\"concept\":\"gap-risk\"}],\"check\":[\"q-3.14.4-1\",\"q-3.14.4-2\",\"q-3.14.4-3\"],\"recap\":{\"takeaways\":[\"Commodities move on supply shocks, storage and scheduled reports; prices react to the surprise.\",\"Locked limit days skip stops: 1R planned became 3.25R. Size for two limit days.\",\"Seasonal patterns are already in the curve; you earn only what it didn't expect.\"],\"next\":\"Next, 3.14.5: crypto, a market that never closes, with much larger volatility and coins that sit on a venue.\"}},\"3.14.5\":{\"unit\":\"3.14\",\"courseId\":\"3.14.5\",\"bridge\":\"In 3.14.4 a locked market skipped stops. Crypto never closes: no weekend gap as in 2.9.8, but thin nights and weekends where stops slip. 2.4.6's ATR sizes the position, and 3.10.2's square-root rule annualises its much larger volatility. Then: where your coins sit.\",\"hook\":{\"prompt\":\"You risk 1% with a stop 2 ATR away. LXC, the synthetic coin, has a daily ATR of 4% of price; LABX's is 1.5%. Compared with a LABX trade, your LXC position value should be…\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"same\",\"label\":\"About the same\",\"feedback\":\"Same risk, not same size. Each LXC unit moves 4% a day against 1.5%, so you need less of it.\"},{\"id\":\"smaller\",\"label\":\"About 2.7 times smaller\"},{\"id\":\"bigger\",\"label\":\"Bigger\",\"feedback\":\"A wider stop means fewer units for the same risk, not more. LXC's stop is 2.7 times wider in %.\"}],\"answer\":\"smaller\"},\"compare\":\"You picked {yours}. 4% ÷ 1.5% = 2.67: with a stop 2.67 times wider in %, the same 1% risk buys a position 2.67 times smaller.\",\"concept\":\"crypto-market-structure\"},\"learn\":[{\"kind\":\"worked\",\"title\":\"Same risk, smaller position\",\"lines\":[\"Account 10,000.00, risk 1% = 100.00, stop 2 ATR away, before costs.\",\"LABX at 100.00, ATR 1.50: stop 3.00 away. 100.00 ÷ 3.00 = 33 units, 3,300.00 of LABX.\",\"LXC at 30,000.00, ATR 1,200.00: stop 2,400.00 away. 100.00 ÷ 2,400.00 = 0.0417 coins.\",\"LXC position value, in vUSD: ?\"],\"ask\":{\"answer\":1250,\"tolerance\":1.5,\"unit\":\"vUSD\",\"feedback\":[{\"value\":3300,\"text\":\"That's the LABX position. Now LXC: 0.0417 coins × 30,000.00.\"},{\"value\":30000,\"text\":\"That's one whole coin. The budget covers only 0.0417 of one.\"}],\"correct\":\"Right: about 1,250.00, against 3,300.00 of LABX. Same 100.00 at risk, 2.6 times smaller.\"},\"after\":\"That's [[volatility-sizing]]: the coin's position is smaller because each unit moves more. Crypto venues sell fractions of a coin, so the size can match the risk closely.\",\"concept\":\"percent-volatility-sizing\"},{\"kind\":\"explain\",\"title\":\"A market that never closes\",\"text\":\"Crypto trades 24 hours a day, every day, with no closing auction. Weekends and quiet hours are thin: spreads widen and stops slip. A 4% daily move annualises to about 76% (4% × √365, since it trades every day); large stock indices usually run nearer 15–20%. In sell-offs, coins tend to fall together.\"},{\"kind\":\"figure\",\"title\":\"Where your coins live\",\"text\":\"When FTX failed in November 2022, withdrawals froze and customer money turned out to have been used by an affiliated trading firm. [[counterparty-risk|Counterparty risk]] is per venue. In the US, SIPC covers securities at a failed broker, not crypto that isn't a security.\",\"figure\":{\"kind\":\"flow\",\"start\":\"where\",\"nodes\":[{\"id\":\"where\",\"text\":\"Are your coins held on an exchange?\",\"kind\":\"question\",\"yes\":\"venue\",\"no\":\"self\"},{\"id\":\"venue\",\"text\":\"The exchange holds the keys; your balance is a claim on the firm\",\"kind\":\"pause\",\"next\":\"fail\"},{\"id\":\"fail\",\"text\":\"If it fails, withdrawals freeze and you queue with its creditors\",\"kind\":\"end\"},{\"id\":\"self\",\"text\":\"Self-custody: no venue risk, but lost keys mean lost coins\",\"kind\":\"end\"}],\"steps\":[\"On an exchange, the venue holds the keys. Your balance is a claim on the firm.\",\"If it fails, withdrawals freeze and you queue with its other creditors.\",\"Self-custody removes venue risk and adds yours: lose the keys and the coins are gone.\"]},\"concept\":\"counterparty-risk\"},{\"kind\":\"match\",\"title\":\"Name the risk\",\"prompt\":\"Match each event to the kind of risk it is.\",\"columns\":[\"Event\",\"Risk\"],\"pairs\":[{\"left\":\"A dollar stablecoin trades at 0.90\",\"right\":\"A de-peg: the 'stable' token loses its value\",\"wrong\":\"A stablecoin is only as good as its reserves and design. Below 1.00, it has de-pegged.\"},{\"left\":\"8% of a token's supply unlocks next week\",\"right\":\"Scheduled new supply\",\"wrong\":\"A token unlock releases locked coins on a known date: supply that holders may sell.\"},{\"left\":\"An exchange's wallet is hacked\",\"right\":\"Venue risk\",\"wrong\":\"Coins held on that exchange share its security and its solvency.\"},{\"left\":\"A regulator sues a large exchange\",\"right\":\"Regulatory headline risk\",\"wrong\":\"A lawsuit can freeze services or delist tokens, and moves prices within minutes.\"}],\"correct\":\"Right. Real cases: an algorithmic stablecoin collapsed in 2022, and a large reserve-backed one briefly fell below its peg in March 2023, when a bank holding part of its reserves failed.\",\"concept\":\"counterparty-risk\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Rules differ by place and change often. The EU licenses crypto service providers under MiCA and caps retail crypto CFDs at 2:1; the US has had spot bitcoin and ether ETFs since 2024. On-chain 'fundamentals' are noisy signals, grade C to D. [[grid-trading|Grid]] and [[martingale]] bots, heavily promoted in crypto, are grade F.\"},{\"kind\":\"worked\",\"title\":\"One venue fails\",\"lines\":[\"You hold 10,000.00 of synthetic crypto: venue A 4,000.00, venue B 3,000.00, venue C 2,000.00, your own wallet 1,000.00.\",\"Any one venue can fail. Plan for the worst: the biggest balance.\",\"Worst single-venue loss, as % of your holdings: ?\"],\"ask\":{\"answer\":40,\"tolerance\":0,\"unit\":\"%\",\"feedback\":[{\"value\":30,\"text\":\"That's venue B. Plan for the worst case: venue A holds 4,000.00.\"},{\"value\":90,\"text\":\"In this drill venues fail one at a time: only the largest balance counts.\"}],\"correct\":\"Right: 40%. To cap any one failure at 25%, no venue may hold more than 2,500.00.\"},\"after\":\"Spreading across venues limits the damage from one failure; it doesn't help if they fail together. [[self-custody|Self-custody]] moves the risk to you: keys, backups and mistakes.\",\"concept\":\"counterparty-risk\"},{\"kind\":\"fields\",\"title\":\"Your custody rules\",\"prompt\":\"Write your crypto rules: the most you'll keep on any one venue, and a cap on open risk over a weekend.\",\"fields\":[{\"id\":\"venueCap\",\"label\":\"Most on any one venue, % of your crypto\",\"kind\":\"stepper\",\"min\":5,\"max\":100,\"step\":5,\"unit\":\"%\",\"default\":40},{\"id\":\"weekendRisk\",\"label\":\"Most open risk over a weekend, % of equity\",\"kind\":\"stepper\",\"min\":0.5,\"max\":5,\"step\":0.5,\"unit\":\"%\",\"default\":2},{\"id\":\"keys\",\"label\":\"Where your key backup lives\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Two paper copies in two places, never online\",\"required\":false}],\"valid\":{\"field\":\"venueCap\",\"lte\":25},\"feedback\":[{\"when\":{\"field\":\"venueCap\",\"gt\":25},\"text\":\"At {venueCap}% on one venue, a single failure takes more than a quarter of your crypto.\"}],\"correct\":\"Saved. One venue failing now costs at most a quarter of your crypto, and weekend exposure has a ceiling.\",\"concept\":\"counterparty-risk\"}],\"check\":[\"q-3.14.5-1\",\"q-3.14.5-2\",\"q-3.14.5-3\"],\"recap\":{\"takeaways\":[\"24/7, no closing auction, thin weekends: 4% a day annualises to about 76%.\",\"Size from volatility: same 1% risk, an LXC position about 2.6 times smaller than LABX.\",\"Coins on a venue are a claim on it: cap each venue; self-custody trades for key risk.\"],\"next\":\"Next, 3.14.6: perpetual swaps, crypto's futures with no expiry, and the funding payments that keep them near spot.\"}},\"3.14.6\":{\"unit\":\"3.14\",\"courseId\":\"3.14.6\",\"bridge\":\"In 3.14.5 you sized LXC spot. Venues also list perpetuals: 3.14.1's futures with no expiry, so nothing forces them back to spot. Funding does that job. It also shows crowding, which 3.9.1 taught you to read as a condition, not a trigger.\",\"hook\":{\"prompt\":\"You hold a 100,000 vUSD long in the LXC perpetual. Funding for this 8-hour interval is +0.03%. Who pays whom, and how much?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"You receive 30 vUSD\",\"feedback\":\"Positive funding flows from longs to shorts. You're long, so you pay.\"},{\"id\":\"b\",\"label\":\"You pay 30 vUSD to the shorts\"},{\"id\":\"c\",\"label\":\"You pay 300 vUSD\",\"feedback\":\"0.03% is 0.0003: 100,000 × 0.0003 = 30, not 300.\"},{\"id\":\"d\",\"label\":\"Nobody pays\",\"feedback\":\"Funding is charged at every interval while the rate isn't zero. It's a payment between traders.\"}],\"answer\":\"b\"},\"compare\":\"You picked {yours}. Positive funding: longs pay shorts. 100,000.00 × 0.03% = 30.00 for this interval, and there are three a day.\",\"concept\":\"funding-rate\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"A future with no expiry\",\"text\":\"A [[perpetual-swap]] is a future that never expires, so nothing forces it back to spot. [[funding-rate|Funding]] does that job: every 8 hours (every 1 or 4 on some venues), longs and shorts pay each other. When the perpetual trades above its spot index, funding is positive and longs pay shorts, which pulls the price back.\"},{\"kind\":\"worked\",\"title\":\"Where the rate comes from\",\"lines\":[\"One large venue's method, as third parties describe it: funding = [[premium-index]] + clamp(interest − premium, −0.05%, +0.05%).\",\"Interest is fixed at 0.01% per 8 hours. With a small premium, the clamp brings funding back to 0.01%.\",\"Now the premium averages 0.08%. Interest − premium = −0.07%, clamped to −0.05%.\",\"Funding for the interval, in %: ?\"],\"ask\":{\"answer\":0.03,\"tolerance\":0.001,\"unit\":\"%\",\"feedback\":[{\"value\":0.01,\"text\":\"That's the default when the premium is small. Here it's 0.08%: 0.08% − 0.05%.\"},{\"value\":0.08,\"text\":\"Add the clamped term: 0.08% + (−0.05%).\"},{\"value\":0.15,\"text\":\"The clamped term is negative: interest minus premium is −0.07%, capped at −0.05%.\"}],\"correct\":\"Right: 0.03%, the hook's rate. The richer the perpetual, the more longs pay.\"},\"after\":\"Venues differ in intervals, caps and formulas. Read the contract page before you trade one.\",\"concept\":\"funding-rate\"},{\"kind\":\"predict\",\"title\":\"What funding costs\",\"prompt\":\"A 5× long: 50,000.00 of LXC perpetual on 10,000.00 margin, held 30 days at +0.01% every 8 hours. What share of the margin goes to funding?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"0.9%\",\"feedback\":\"That charges funding on the margin. It's charged on the 50,000.00 position.\"},{\"id\":\"b\",\"label\":\"1.5%\",\"feedback\":\"That's one payment a day. Funding comes every 8 hours: three a day.\"},{\"id\":\"c\",\"label\":\"4.5%\"},{\"id\":\"d\",\"label\":\"10.95%\",\"feedback\":\"10.95% is the yearly rate on the position. Over 30 days, at 5×, it's 4.5% of the margin.\"}],\"answer\":\"c\"},\"reveal\":\"50,000.00 × 0.01% × 3 × 30 = 450.00: 4.5% of the margin in a month, before any price move. 0.01% every 8 hours is 10.95% a year on the position, and leverage multiplies it as a share of margin.\",\"concept\":\"funding-rate\"},{\"kind\":\"figure\",\"title\":\"Mark price and last price\",\"text\":\"Venues value positions at the [[mark-price|mark price]], built from a spot index across several venues, not at the last trade. A thin moment on one venue can print a wick that the mark price ignores.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":30050,\"h\":30180,\"l\":29960,\"c\":30120},{\"o\":30120,\"h\":30210,\"l\":30010,\"c\":30040},{\"o\":30040,\"h\":30090,\"l\":29880,\"c\":29930},{\"o\":29930,\"h\":30020,\"l\":29850,\"c\":29990},{\"o\":29990,\"h\":30070,\"l\":29910,\"c\":29960},{\"o\":29960,\"h\":30010,\"l\":29870,\"c\":29900},{\"o\":29900,\"h\":29940,\"l\":28900,\"c\":29840},{\"o\":29840,\"h\":29950,\"l\":29790,\"c\":29910},{\"o\":29910,\"h\":30030,\"l\":29880,\"c\":30000},{\"o\":30000,\"h\":30090,\"l\":29940,\"c\":30050}],\"range\":[28700,30300],\"describe\":\"Ten candles of LXC last price around 30,000. The seventh has a long lower wick to 28,900 and closes at 29,840; the mark price stays near the closes.\"},\"steps\":[{\"text\":\"Last price on one venue: a thin moment, and a wick to 28,900.\",\"layers\":[{\"kind\":\"marker\",\"index\":6,\"price\":28900,\"label\":\"LAST 28,900\",\"role\":\"down\"}]},{\"text\":\"The mark price, from a multi-venue index, barely moved: its low was 29,780.\",\"layers\":[{\"kind\":\"line\",\"values\":[30110,30050,29950,29980,29960,29910,29850,29900,29990,30040],\"role\":\"accent\",\"label\":\"MARK\"},{\"kind\":\"marker\",\"index\":6,\"price\":29780,\"label\":\"MARK LOW 29,780\",\"role\":\"accent\"}]},{\"text\":\"Liquidation at 29,200 uses mark price: no liquidation. A last-price stop there would have filled.\",\"layers\":[{\"kind\":\"level\",\"price\":29200,\"role\":\"stop\",\"label\":\"LIQUIDATION 29,200\"}]}]},\"concept\":\"perpetual-swap\"},{\"kind\":\"explain\",\"title\":\"Funding as positioning\",\"text\":\"Funding also shows positioning. Persistently positive funding means longs are crowded and paying to stay in. That's a condition, not a trigger (3.9.1): crowded trades can stay crowded. As a signal it rates C. Research finds perpetual prices stray from their no-arbitrage value more than FX rates do, together across coins, though less over time.\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Long spot plus short perpetual collects positive funding with little price risk: a basis trade, a form of carry (3.13.3), grade B. It pays while funding is positive and costs when it turns negative. The short leg still carries venue and liquidation risk.\"},{\"kind\":\"worked\",\"title\":\"Your turn: the ticket\",\"lines\":[\"Ticket: LXC perpetual, long, margin 10,000.00, position 30,000.00 (3×).\",\"Funding is +0.01% every 8 hours. You plan to hold 14 days.\",\"Total funding you expect to pay at this rate, in vUSD: ?\"],\"ask\":{\"answer\":126,\"tolerance\":1,\"unit\":\"vUSD\",\"feedback\":[{\"value\":42,\"text\":\"Funding is charged on the 30,000.00 position, three times a day: 30,000.00 × 0.01% × 3 × 14.\"},{\"value\":3,\"text\":\"That's one interval. 14 days hold 42 of them.\"}],\"correct\":\"Right: 126.00, before any price move. It goes on the ticket before you confirm.\"},\"after\":\"The rate changes every interval: if longs crowd in, it rises and so does your cost. Check it daily, like a swap.\",\"concept\":\"funding-rate\"}],\"check\":[\"q-3.14.6-1\",\"q-3.14.6-2\",\"q-3.14.6-3\"],\"recap\":{\"takeaways\":[\"Funding keeps a perpetual near spot: when positive, longs pay shorts, usually every 8 hours.\",\"0.01% per 8 hours is 10.95% a year on the position: 126.00 over 14 days at 3×.\",\"Persistently positive funding means crowded longs: a condition to respect, not a trigger.\"],\"next\":\"Next, 3.14.7: leverage on a perpetual, where its liquidation price sits, and how forced selling cascades.\"}},\"3.14.7\":{\"unit\":\"3.14\",\"courseId\":\"3.14.7\",\"bridge\":\"In 3.14.6 funding cost a 5× long 4.5% of its margin in a month. Leverage has a sharper cost: liquidation, 2.14.6's margin close-out at a price you can compute. As in 1.4.4: stop first, size from it, then let leverage set only the margin.\",\"hook\":{\"prompt\":\"Long LXC at 30,000 with 10× isolated leverage. Maintenance margin is 0.5%. Roughly where are you liquidated?\",\"control\":{\"kind\":\"slider\",\"min\":20000,\"max\":30000,\"step\":50,\"start\":25000,\"answer\":27150,\"tolerance\":100,\"feedback\":[{\"from\":20000,\"to\":26950,\"text\":\"Too far. At 10× the margin covers only a 10% fall, and the venue doesn't wait for all of it.\"},{\"from\":27000,\"to\":27000,\"text\":\"That's −10%, where the margin is all gone. The venue liquidates while 0.5% maintenance is left: −9.5%.\"},{\"from\":27300,\"to\":30000,\"text\":\"Too close. 10× margin is 10% of the position; liquidation comes when about 9.5% is gone.\"}]},\"compare\":\"You picked {yours}. Liquidation ≈ 30,000 × (1 − 1 ÷ 10 + 0.005) = 27,150, a 9.5% fall. Exact formulas vary by venue.\",\"concept\":\"liquidation-price\"},\"learn\":[{\"kind\":\"worked\",\"title\":\"Where liquidation sits\",\"lines\":[\"Isolated long: [[liquidation-price]] ≈ entry × (1 − 1 ÷ leverage + maintenance margin rate). Venues' exact formulas differ.\",\"10×: 30,000 × (1 − 0.10 + 0.005) = 27,150, a 9.5% fall.\",\"25×: 30,000 × (1 − 0.04 + 0.005) = 28,950, a 3.5% fall.\",\"50×: 30,000 × (1 − 0.02 + 0.005) = ?\"],\"ask\":{\"answer\":29550,\"tolerance\":1,\"feedback\":[{\"value\":29400,\"text\":\"That leaves out the maintenance margin. Liquidation comes 0.5% earlier.\"},{\"value\":15000,\"text\":\"1 ÷ 50 is 0.02, not 0.5.\"}],\"correct\":\"Right: 29,550, a 1.5% fall: ordinary noise for a coin that moves 4% a day.\"},\"after\":\"At 50× the margin covers a 2% move, and the venue liquidates once only the 0.5% maintenance is left. More leverage pulls liquidation toward entry.\",\"concept\":\"liquidation-price\"},{\"kind\":\"worked\",\"title\":\"Stop first, then leverage\",\"lines\":[\"1. Stop: 3% below entry, at 29,100. Risk 1% of 10,000.00 = 100.00.\",\"2. Size from the stop: 100.00 ÷ 3% = 3,333.33 of LXC.\",\"3. Leverage sets only the margin: 333.33 at 10×, 133.33 at 25×. The risk stays 100.00.\",\"4. Check: at 25×, liquidation is 28,950. Gap between stop and liquidation, in vUSD of price: ?\"],\"ask\":{\"answer\":150,\"tolerance\":0,\"feedback\":[{\"value\":1050,\"text\":\"That's entry to liquidation. Measure from the stop, 29,100.\"},{\"value\":900,\"text\":\"That's entry to stop. Measure from the stop down to the liquidation price.\"}],\"correct\":\"Right: 150, 0.5% of price. A wick on the mark price can cover that before your stop fills.\"},\"after\":\"This course's design rule: liquidation at least twice as far as the stop. At 10×, 9.5% against a 3% stop passes. At 25×, 3.5% fails, and a liquidation charges a fee on top.\",\"concept\":\"liquidation-price\"},{\"kind\":\"explain\",\"title\":\"When liquidations go wrong\",\"text\":\"[[isolated-margin|Isolated margin]] risks only that position's margin. [[cross-margin|Cross margin]] lets positions share the account: fewer liquidations, but one bad trade can drain everything. If a liquidation closes below zero equity, the venue's [[insurance-fund]] covers the gap; when it runs dry, [[auto-deleveraging]] closes profitable traders on the other side.\"},{\"kind\":\"match\",\"title\":\"Isolated or cross?\",\"prompt\":\"Sort each statement under the margin mode it describes.\",\"columns\":[\"Statement\",\"Margin mode\"],\"pairs\":[{\"left\":\"A liquidation can take only this position's margin\",\"right\":\"Isolated\",\"wrong\":\"Capping the loss at one position's margin is what isolated margin does.\"},{\"left\":\"Gains on one position hold up another\",\"right\":\"Cross\",\"wrong\":\"Sharing the balance across positions is cross margin.\"},{\"left\":\"One bad trade can drain the whole account\",\"right\":\"Cross\",\"wrong\":\"Only cross margin lets one position reach the rest of the account.\"},{\"left\":\"You top up each position yourself, or it's closed\",\"right\":\"Isolated\",\"wrong\":\"With isolated margin, each position stands on its own margin.\"}],\"correct\":\"Right. Isolated caps the damage per position; cross spreads it across the account.\",\"concept\":\"leverage\"},{\"kind\":\"figure\",\"title\":\"A liquidation cascade\",\"text\":\"A liquidation cascade is a [[stop-cascade]] with leverage. In October 2025, a sell-off produced what was reported as the largest day of crypto liquidations on record, and several venues used auto-deleveraging.\",\"figure\":{\"kind\":\"flow\",\"start\":\"drop\",\"nodes\":[{\"id\":\"drop\",\"text\":\"Price drops, often in thin hours\",\"kind\":\"pause\",\"next\":\"liq\"},{\"id\":\"liq\",\"text\":\"Highly levered positions hit their liquidation prices\",\"kind\":\"pause\",\"next\":\"sell\"},{\"id\":\"sell\",\"text\":\"The venue sells them at market\",\"kind\":\"pause\",\"next\":\"lower\"},{\"id\":\"lower\",\"text\":\"The selling pushes price into the next layer of liquidations\",\"kind\":\"end\"}],\"steps\":[\"A fall starts, often in thin hours or on a weekend.\",\"The most levered longs reach their liquidation prices first.\",\"Their positions are sold at market, into a thin book.\",\"Price falls further, into the next layer of liquidations: the chain feeds itself.\"]},\"concept\":\"liquidation-cascade\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Leverage multiplies volatility, not edge. Account move ≈ price move × [[effective-leverage]]: at 20×, a 5% move against you is 100% of the margin. EU rules cap retail crypto CFDs at 2:1.\"},{\"kind\":\"fields\",\"title\":\"Your turn: pick the leverage\",\"prompt\":\"LXC at 30,000, account 10,000.00, risk 1%, stop 3%, maintenance margin 0.5%. Choose leverage so liquidation sits at least twice as far as your stop.\",\"fields\":[{\"id\":\"leverage\",\"label\":\"Leverage\",\"kind\":\"stepper\",\"min\":1,\"max\":50,\"step\":1,\"unit\":\"×\",\"default\":25}],\"valid\":{\"field\":\"leverage\",\"lte\":15},\"feedback\":[{\"when\":{\"field\":\"leverage\",\"gt\":15},\"text\":\"At {leverage}×, liquidation sits 1 ÷ {leverage} − 0.5% below entry: under 6%, twice your 3% stop.\"}],\"correct\":\"Right. At 15×, the most that passes: 1 ÷ 15 − 0.5% = 6.17%. Risk is still 100.00, set by the stop; leverage only set the margin.\",\"concept\":\"liquidation-price\"}],\"check\":[\"q-3.14.7-1\",\"q-3.14.7-2\",\"q-3.14.7-3\"],\"recap\":{\"takeaways\":[\"Liquidation ≈ entry × (1 − 1 ÷ L + maintenance): 27,150 at 10×, 29,550 at 50×.\",\"Stop first, size from it; leverage sets margin. Keep liquidation twice the stop's distance: 15× here.\",\"Cascades feed on forced selling; insurance funds and auto-deleveraging can close even winners.\"],\"next\":\"Next, 3.14.8: bonds and rates, where duration and DV01 turn a yield move into money.\"}},\"3.14.8\":{\"unit\":\"3.14\",\"courseId\":\"3.14.8\",\"bridge\":\"In 3.14.7 leverage turned small moves into large ones. Bonds have their own amplifier: duration. 3.6.1 showed prices fall when yields rise; here you measure how far, and turn a yield move into money with DV01, as 3.14.1's multiplier did for points.\",\"hook\":{\"prompt\":\"A synthetic 10-year note has a duration of 8.95. Yields rise one percentage point. Its price moves by about…\",\"control\":{\"kind\":\"slider\",\"min\":-20,\"max\":20,\"step\":0.5,\"unit\":\"%\",\"start\":0,\"answer\":-9,\"tolerance\":0.5,\"feedback\":[{\"from\":0,\"to\":20,\"text\":\"Yields up, prices down: a bond's price moves opposite to its yield.\"},{\"from\":-20,\"to\":-10,\"text\":\"Too much. Duration 8.95 means about 8.95% per percentage point.\"},{\"from\":-8,\"to\":-0.5,\"text\":\"Too little. Duration 8.95 means about 8.95% per percentage point.\"}]},\"compare\":\"You picked {yours}. Duration 8.95 × 1 point ≈ −8.95%. The exact fall is a little smaller, −8.52%, because of convexity.\",\"concept\":\"bond-duration\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Price, yield, duration\",\"text\":\"A bond pays coupons and its face value at maturity. Its price and [[yield]] move in opposite directions (3.6.1). [[duration|Duration]] says how far: roughly the percentage price change for a one-point change in yield. LXN's note has a duration of 8.95, so a one-point rise costs about 8.95%.\"},{\"kind\":\"worked\",\"title\":\"The line bends\",\"lines\":[\"LXN tracks a synthetic 10-year note: a 2.16% coupon, paid twice a year, priced at 100.00. Duration 8.95.\",\"Duration's estimate: yields +1 point → −8.95%; −1 point → +8.95%.\",\"Repriced exactly: +1 point → −8.52%; −1 point → +9.42%.\",\"How much smaller is the real fall than the estimate, in percentage points: ?\"],\"ask\":{\"answer\":0.43,\"tolerance\":0.01,\"feedback\":[{\"value\":0.47,\"text\":\"That's the rise: 9.42 − 8.95. Compare the fall: 8.95 − 8.52.\"},{\"value\":17.47,\"text\":\"Compare the estimate with the exact fall, not the fall with the rise.\"}],\"correct\":\"Right: 0.43 points. Falls are smaller, and rises larger, than duration says.\"},\"after\":\"That bend is [[convexity]]. It's small for small moves, so duration works for everyday sizing; for big moves, reprice the bond.\",\"concept\":\"bond-duration\"},{\"kind\":\"worked\",\"title\":\"DV01: money per basis point\",\"lines\":[\"[[dv01|DV01]] ≈ duration × value × 0.0001: the money change for one [[basis-point]] of yield.\",\"1,000,000.00 of the note at 100.00, duration 8.95: 8.95 × 1,000,000.00 × 0.0001 = 895.00 per basis point.\",\"A surprise lifts yields 25 basis points. P&L of the long: ?\"],\"ask\":{\"answer\":-22375,\"tolerance\":1,\"unit\":\"vUSD\",\"feedback\":[{\"value\":22375,\"text\":\"Check the sign: yields up, price down. The long loses.\"},{\"value\":-2237.5,\"text\":\"25 basis points × 895.00, not 2.5.\"}],\"correct\":\"Right: −22,375.00, 2.24% of the position.\"},\"after\":\"DV01 adds across positions, so a desk sums it to see its total rate risk in money. Short bonds carry far less DV01 per million than long ones.\",\"concept\":\"dv01\"},{\"kind\":\"match\",\"title\":\"Rate instruments\",\"prompt\":\"Match each rate instrument to its feature.\",\"columns\":[\"Instrument\",\"Feature\"],\"pairs\":[{\"left\":\"Treasury and Bund futures\",\"right\":\"Track the cheapest bond to deliver, so their DV01 drifts\",\"wrong\":\"Bond futures deliver one of a basket of bonds; the cheapest one drives the price and the DV01.\"},{\"left\":\"Yield-quoted futures\",\"right\":\"A fixed money value per basis point\",\"wrong\":\"Quoted in yield, they pay a set amount per basis point: DV01 is fixed by design.\"},{\"left\":\"Short-term rate futures, such as SOFR\",\"right\":\"Price the expected path of policy rates (3.7)\",\"wrong\":\"Priced as 100 minus the expected rate, they show where markets think policy is going.\"},{\"left\":\"Bond ETFs\",\"right\":\"A fund of bonds traded like a share, with no expiry\",\"wrong\":\"An ETF holds bonds and rolls them itself; you never roll or face delivery.\"}],\"correct\":\"Right. Same rates, different wrappers: check the DV01 of whatever you trade.\",\"concept\":\"dv01\"},{\"kind\":\"figure\",\"title\":\"One surprise, many markets\",\"text\":\"Rates feed into almost every price. Even if you trade only stocks, a rate surprise reaches your positions through several doors at once.\",\"figure\":{\"kind\":\"flow\",\"start\":\"cpi\",\"nodes\":[{\"id\":\"cpi\",\"text\":\"A hot CPI print: more hikes priced, yields jump\",\"kind\":\"pause\",\"next\":\"fx\"},{\"id\":\"fx\",\"text\":\"FX carry shifts; CFD and swap financing rise\",\"kind\":\"pause\",\"next\":\"fut\"},{\"id\":\"fut\",\"text\":\"Index futures' fair value over spot widens\",\"kind\":\"pause\",\"next\":\"eq\"},{\"id\":\"eq\",\"text\":\"Stock valuations fall, long-duration growth most; options reprice\",\"kind\":\"end\"}],\"steps\":[\"A hot CPI print: markets price more rate hikes, and yields jump.\",\"FX: rate differentials and carry move; CFD overnight funding rises (2.14).\",\"Futures: more financing raises index futures' fair value over spot (3.14.3).\",\"Stocks: a higher discount rate lowers valuations, long-duration growth most (3.8.3). Options reprice too (4.1).\"]},\"concept\":\"bond-duration\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Curve trades weighted by DV01, such as 2-year against 10-year, size each leg so both move the same money per basis point. That's Advanced to Expert ground; the [[yield-curve]] itself is in 3.6.\"},{\"kind\":\"fields\",\"title\":\"Your turn: cut the rate risk\",\"prompt\":\"You hold 3 LXN contracts, DV01 80.00 vUSD each, on a 100,000.00 account. Keep as many as you can while a 10 bp surprise costs at most 1%.\",\"fields\":[{\"id\":\"contracts\",\"label\":\"LXN contracts to keep\",\"kind\":\"stepper\",\"min\":0,\"max\":3,\"step\":1,\"default\":3}],\"valid\":{\"field\":\"contracts\",\"eq\":1},\"feedback\":[{\"when\":{\"field\":\"contracts\",\"gte\":2},\"text\":\"Each contract loses 80.00 × 10 = 800.00 on a 10 bp move. Two lose 1,600.00, over the 1,000.00 cap.\"},{\"when\":{\"field\":\"contracts\",\"eq\":0},\"text\":\"Flat is safe, but one contract fits: 800.00 is within 1,000.00.\"}],\"correct\":\"Right: 1 contract, 800.00 on a 10 bp surprise. Three would have lost 2,400.00.\",\"concept\":\"dv01\"}],\"check\":[\"q-3.14.8-1\",\"q-3.14.8-2\",\"q-3.14.8-3\"],\"recap\":{\"takeaways\":[\"Price and yield move opposite; duration 8.95 means about −8.95% for a one-point rise.\",\"DV01 is money per basis point: 895.00 on 1,000,000 at duration 8.95; 25 bp costs 22,375.00.\",\"One rate surprise reaches FX carry, CFD funding, futures fair value, stock valuations and options.\"],\"next\":\"Next: the 3.14 checkpoint closes Level 3. Level 4 opens with unit 4.1, Options and volatility: calls and puts, the right without the obligation.\"}}}");
